    out = [row[:] for row in grid]
    marks = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != 0]

    twos = [(r, c) for r, c, v in marks if v == 2]
    verticals = []

    def put(r, c, value):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = value

    for r, c, v in marks:
        if v == 1:
            put(r, c + 1, 5)
            put(r, c + 2, 5)
            put(r - 1, c + 2, 1)
        elif v == 2:
            for x in range(c - 4, c + 1):
                put(r, x, 2 if x in (c - 4, c) else 5)
        elif v == 3:
            verticals.append((c, r, min(h - 1, r + 3)))
            for y in range(r, r + 4):
                put(y, c, 3 if y in (r, r + 3) else 5)
        elif v == 6:
            verticals.append((c, max(0, r - 6), r))
            for y in range(r - 6, r + 1):
                put(y, c, 6 if y in (r - 6, r) else 5)

    # At crossings, mark the junction and extend a diagonal trail down-left.
    for r, c in twos:
        for vc, top, bottom in verticals:
            if top <= r <= bottom and c - 4 <= vc <= c:
                put(r, vc, 4)
                rr, cc = r + 1, vc - 1
                while rr < h and cc >= 0:
                    put(rr, cc, 4)
                    rr += 1
                    cc -= 1

    # Original objects remain visible.
    for r, c, v in marks:
        out[r][c] = v

    return out
